package com.bank.treasury;

import java.util.logging.*;

public class ContainerWaterDemo {
    private static final Logger log = Logger.getLogger(ContainerWaterDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        LiquidityWindowAnalyzer analyzer = new LiquidityWindowAnalyzer();

        // Daily end-of-day balances (in lakhs) for a window search
        int[] balances = {1, 8, 6, 2, 5, 4, 8, 3, 7};
        int best = analyzer.maxReserve(balances);
        log.info(() -> "Max reserve window value: " + best);
    }
}

