class LiquidityWindowAnalyzer {
    private static final Logger log = Logger.getLogger(LiquidityWindowAnalyzer.class.getName());

    // Opposite-end greedy: move the shorter wall. O(n) time, O(1) space.
    int maxReserve(int[] h) {
        int left = 0, right = h.length - 1, best = 0;
        while (left < right) {
            int height = Math.min(h[left], h[right]);
            int width = right - left;
            int area = height * width;
            if (area > best) {
                best = area;
                int fl = left, fr = right, fa = area;
                log.fine(() -> "New best " + fa + " between day " + fl + " and " + fr);
            }
            if (h[left] < h[right]) left++;  // shorter wall → move it
            else right--;
        }
        return best;
    }
}

